save('/cart','Корзина',heading('ВАШ ЗАКАЗ','Корзина','Проверьте выбранные ароматы, объёмы и количество.').replace('<h1>Корзина</h1>','<h1 id="cart-page-title">Корзина</h1>')+'<div id="cart-root"><section class="cart-page-content" aria-labelledby="cart-page-title">'+cart_markup+'</section></div>','<script src="/cart-state.js"></script>')

