# Kazakh and English dictionaries; the Russian text stays the key, so a text edited
# later simply shows in Russian until it is translated again instead of going stale.
I18N=Path('site/data/i18n'); D.joinpath('i18n').mkdir(exist_ok=True)
read=lambda name:json.loads(I18N.joinpath(name).read_text())
rules=read('rules.json'); strings=read('ui.json'); notes=read('notes.json'); descriptions=read('products.json')
wrap=lambda data:'arafanI18n('+json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')+');\n'
for index,lang in enumerate(['kk','en']):
 D.joinpath('i18n',f'{lang}.js').write_text(wrap({'strings':{k:v[lang] for k,v in strings.items()},'notes':{k:v[lang] for k,v in notes.items()},'rules':[[r[0],r[1+index]] for r in rules]}))
 D.joinpath('i18n',f'{lang}-products.js').write_text(wrap({'strings':{ru:text for p in ps if p['id'] in descriptions for ru,text in zip(p.get('descriptionParagraphs') or [],descriptions[p['id']][lang])}}))
